"""The C runtime emitted at the top of every generated file.

Everything the compiler cannot express as a direct C construct lives here:
panics with a source line, integer power, strings, lists, files, tasks, the
conversions and the small amount of dynamic storage the standard library
needs.
"""

PRELUDE = r"""/* generated by the baton compiler - do not edit */
#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>

/* -- runtime ---------------------------------------------------------- */

static int64_t bt_line = 0;

static void bt_panic(const char *message, int64_t line) {
    fflush(stdout);
    fprintf(stderr, "panic: %s (line %lld)\n", message, (long long)line);
    exit(1);
}

static void bt_null_check(const void *p, int64_t line) {
    if (!p) bt_panic("null pointer", line);
}

static int64_t bt_ipow(int64_t base, int64_t exp) {
    if (exp < 0) bt_panic("negative exponent in '**'", bt_line);
    uint64_t result = 1, b = (uint64_t)base;
    while (exp > 0) {
        if (exp & 1) result *= b;
        b *= b;
        exp >>= 1;
    }
    return (int64_t)result;
}

static double bt_fpow(double base, double exp) {
    return pow(base, exp);
}

static const char *bt_str_dup(const char *s) {
    if (!s) return "";
    size_t n = strlen(s) + 1;
    char *out = (char *)malloc(n);
    if (!out) bt_panic("out of memory", bt_line);
    memcpy(out, s, n);
    return out;
}

static const char *bt_str_cat(const char *a, const char *b) {
    a = a ? a : "";
    b = b ? b : "";
    size_t la = strlen(a), lb = strlen(b);
    char *out = (char *)malloc(la + lb + 1);
    if (!out) bt_panic("out of memory", bt_line);
    memcpy(out, a, la);
    memcpy(out + la, b, lb);
    out[la + lb] = '\0';
    return out;
}

static int64_t bt_str_cmp(const char *a, const char *b) {
    return (int64_t)strcmp(a ? a : "", b ? b : "");
}

static const char *bt_tos_i(int64_t v) {
    char *out = (char *)malloc(32);
    if (!out) bt_panic("out of memory", bt_line);
    snprintf(out, 32, "%lld", (long long)v);
    return out;
}

static const char *bt_tos_u(uint64_t v) {
    char *out = (char *)malloc(32);
    if (!out) bt_panic("out of memory", bt_line);
    snprintf(out, 32, "%llu", (unsigned long long)v);
    return out;
}

static const char *bt_tos_f(double v) {
    char *out = (char *)malloc(48);
    if (!out) bt_panic("out of memory", bt_line);
    snprintf(out, 48, "%.17g", v);
    return out;
}

static const char *bt_tos_b(bool v) {
    return v ? "true" : "false";
}

static const char *bt_tos_c(char v) {
    char *out = (char *)malloc(2);
    if (!out) bt_panic("out of memory", bt_line);
    out[0] = v;
    out[1] = '\0';
    return out;
}

static int64_t bt_toi(const char *s) {
    if (!s) return 0;
    errno = 0;
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (errno != 0 || end == s || *end != '\0') return 0;
    return (int64_t)v;
}

static double bt_tof(const char *s) {
    if (!s) return 0.0;
    errno = 0;
    char *end = NULL;
    double v = strtod(s, &end);
    if (errno != 0 || end == s || *end != '\0') return 0.0;
    return v;
}

static bool bt_tob(const char *s) {
    return s && strcmp(s, "true") == 0;
}

typedef struct { int64_t f0; bool f1; } bt_tryi_result;
typedef struct { double f0; bool f1; } bt_tryf_result;
typedef struct { int64_t f0; bool f1; } bt_indexof_result;

static bt_tryi_result bt_tryi(const char *s) {
    bt_tryi_result r = {0, false};
    if (!s || !*s) return r;
    errno = 0;
    char *end = NULL;
    long long v = strtoll(s, &end, 10);
    if (errno == 0 && end != s && *end == '\0') {
        r.f0 = (int64_t)v;
        r.f1 = true;
    }
    return r;
}

static bt_tryf_result bt_tryf(const char *s) {
    bt_tryf_result r = {0.0, false};
    if (!s || !*s) return r;
    errno = 0;
    char *end = NULL;
    double v = strtod(s, &end);
    if (errno == 0 && end != s && *end == '\0') {
        r.f0 = v;
        r.f1 = true;
    }
    return r;
}

static const char *bt_input(void) {
    char *buf = NULL;
    size_t cap = 0;
    ssize_t n = getline(&buf, &cap, stdin);
    if (n < 0) {
        free(buf);
        return "";
    }
    while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) buf[--n] = '\0';
    return buf;
}

static void bt_div_check(int64_t divisor) {
    if (divisor == 0) bt_panic("division by zero", bt_line);
}

static void bt_mod_check(int64_t divisor) {
    if (divisor == 0) bt_panic("division by zero", bt_line);
}

/* -- strings ---------------------------------------------------------- */

static const char *bt_str_lower(const char *s) {
    if (!s) return "";
    char *out = (char *)malloc(strlen(s) + 1);
    if (!out) bt_panic("out of memory", bt_line);
    size_t i = 0;
    for (; s[i]; i++) {
        char c = s[i];
        out[i] = (c >= 'A' && c <= 'Z') ? (char)(c + ('a' - 'A')) : c;
    }
    out[i] = '\0';
    return out;
}

static const char *bt_str_upper(const char *s) {
    if (!s) return "";
    char *out = (char *)malloc(strlen(s) + 1);
    if (!out) bt_panic("out of memory", bt_line);
    size_t i = 0;
    for (; s[i]; i++) {
        char c = s[i];
        out[i] = (c >= 'a' && c <= 'z') ? (char)(c - ('a' - 'A')) : c;
    }
    out[i] = '\0';
    return out;
}

static const char *bt_str_trim(const char *s) {
    if (!s) return "";
    const char *start = s;
    while (*start == ' ' || *start == '\t' || *start == '\n' || *start == '\r') start++;
    const char *end = start + strlen(start);
    while (end > start && (end[-1] == ' ' || end[-1] == '\t' ||
                           end[-1] == '\n' || end[-1] == '\r')) end--;
    size_t n = (size_t)(end - start);
    char *out = (char *)malloc(n + 1);
    if (!out) bt_panic("out of memory", bt_line);
    memcpy(out, start, n);
    out[n] = '\0';
    return out;
}

static bool bt_str_has(const char *s, const char *needle) {
    return s && needle && strstr(s, needle) != NULL;
}

static bool bt_str_starts(const char *s, const char *prefix) {
    if (!s || !prefix) return false;
    size_t n = strlen(prefix);
    return strncmp(s, prefix, n) == 0;
}

static bool bt_str_ends(const char *s, const char *suffix) {
    if (!s || !suffix) return false;
    size_t ns = strlen(s), nx = strlen(suffix);
    return nx <= ns && memcmp(s + ns - nx, suffix, nx) == 0;
}

/* -- lists ------------------------------------------------------------ */

typedef struct BtList {
    void *data;
    int64_t len;
    int64_t cap;
    int64_t off;
    size_t elem;
    int owns;
} BtList;

static BtList *bt_list_new(size_t elem, int64_t cap) {
    if (cap < 0) cap = 0;
    BtList *l = (BtList *)malloc(sizeof(BtList));
    if (!l) bt_panic("out of memory", bt_line);
    l->elem = elem;
    l->len = 0;
    l->cap = cap;
    l->off = 0;
    l->owns = 1;
    l->data = NULL;
    if (cap > 0) {
        l->data = calloc((size_t)cap, elem);
        if (!l->data) bt_panic("out of memory", bt_line);
    }
    return l;
}

static BtList *bt_list_ensure(BtList *l, size_t elem) {
    if (!l) return bt_list_new(elem, 0);
    l->elem = elem;
    return l;
}

static BtList *bt_list_push(BtList *l, const void *value, size_t elem) {
    l = bt_list_ensure(l, elem);
    if (l->off != 0) {
        /* materialize a view before growing it */
        void *fresh = calloc((size_t)(l->len ? l->len : 1), elem);
        if (!fresh) bt_panic("out of memory", bt_line);
        memcpy(fresh, (char *)l->data + (size_t)l->off * elem,
               (size_t)l->len * elem);
        l->data = fresh;
        l->off = 0;
        l->cap = l->len ? l->len : 1;
        l->owns = 1;
    }
    if (l->len >= l->cap) {
        int64_t cap = l->cap ? l->cap * 2 : 4;
        void *fresh = realloc(l->data, (size_t)cap * elem);
        if (!fresh) bt_panic("out of memory", bt_line);
        memset((char *)fresh + (size_t)l->len * elem, 0,
               (size_t)(cap - l->len) * elem);
        l->data = fresh;
        l->cap = cap;
    }
    memcpy((char *)l->data + (size_t)l->len * elem, value, elem);
    l->len++;
    return l;
}

static void *bt_list_get(BtList *l, int64_t i, int64_t line) {
    if (!l || i < 0 || i >= l->len) bt_panic("index out of range", line);
    return (char *)l->data + (size_t)(l->off + i) * l->elem;
}

static void *bt_list_pop(BtList *l, int64_t line) {
    if (!l || l->len == 0) bt_panic("pop from an empty list", line);
    l->len--;
    return (char *)l->data + (size_t)(l->off + l->len) * l->elem;
}

static int64_t bt_list_len(BtList *l) {
    return l ? l->len : 0;
}

static BtList *bt_list_slice(BtList *l, int64_t start, int64_t end, int64_t line) {
    if (!l) { start = 0; end = 0; }
    if (!l || start < 0 || end < start || end > l->len) {
        bt_panic("slice out of range", line);
    }
    BtList *s = (BtList *)malloc(sizeof(BtList));
    if (!s) bt_panic("out of memory", bt_line);
    s->data = l->data;
    s->len = end - start;
    s->cap = l->cap;
    s->off = l->off + start;
    s->elem = l->elem;
    s->owns = 0;
    return s;
}

static BtList *bt_list_clone(BtList *l) {
    if (!l) return NULL;
    BtList *c = bt_list_new(l->elem, l->len);
    for (int64_t i = 0; i < l->len; i++) {
        c = bt_list_push(c, (char *)l->data + (size_t)(l->off + i) * l->elem, l->elem);
    }
    return c;
}

static void bt_list_reverse(BtList *l) {
    if (!l) return;
    unsigned char tmp[256];
    for (int64_t i = 0, j = l->len - 1; i < j; i++, j--) {
        unsigned char *a = (unsigned char *)l->data + (size_t)(l->off + i) * l->elem;
        unsigned char *b = (unsigned char *)l->data + (size_t)(l->off + j) * l->elem;
        for (size_t k = 0; k < l->elem; k++) {
            if (k < sizeof(tmp)) tmp[k] = a[k];
            else { unsigned char t = a[k]; a[k] = b[k]; b[k] = t; }
        }
        size_t n = l->elem < sizeof(tmp) ? l->elem : sizeof(tmp);
        memcpy(a, b, n);
        memcpy(b, tmp, n);
    }
}


static void bt_list_sort(BtList *l, int (*cmp)(const void *, const void *)) {
    if (!l || l->len < 2) return;
    qsort((char *)l->data + (size_t)l->off * l->elem,
          (size_t)l->len, l->elem, cmp);
}

static bt_indexof_result bt_list_indexof(BtList *l, const void *value,
                                          size_t elem,
                                          int (*cmp)(const void *, const void *)) {
    bt_indexof_result r = {-1, false};
    if (!l) return r;
    for (int64_t i = 0; i < l->len; i++) {
        void *item = (char *)l->data + (size_t)(l->off + i) * l->elem;
        if (cmp(item, value) == 0) {
            r.f0 = i;
            r.f1 = true;
            return r;
        }
    }
    return r;
}

static const char *bt_str_slice(const char *s, int64_t start, int64_t end,
                                int64_t line) {
    if (!s) { start = 0; end = 0; }
    int64_t n = (int64_t)strlen(s);
    if (start < 0 || end < start || end > n) bt_panic("slice out of range", line);
    int64_t len = end - start;
    char *out = (char *)malloc((size_t)len + 1);
    if (!out) bt_panic("out of memory", bt_line);
    memcpy(out, s + start, (size_t)len);
    out[len] = '\0';
    return out;
}

static BtList *bt_str_split(const char *s, const char *sep) {
    if (!s) s = "";
    if (!sep || !*sep) {
        BtList *one = bt_list_new(sizeof(const char *), 1);
        const char *copy = bt_str_dup(s);
        one = bt_list_push(one, &copy, sizeof(copy));
        return one;
    }
    BtList *out = bt_list_new(sizeof(const char *), 4);
    size_t step = strlen(sep);
    const char *at = s;
    while (1) {
        const char *hit = strstr(at, sep);
        size_t n = hit ? (size_t)(hit - at) : strlen(at);
        char *part = (char *)malloc(n + 1);
        if (!part) bt_panic("out of memory", bt_line);
        memcpy(part, at, n);
        part[n] = '\0';
        const char *value = part;
        out = bt_list_push(out, &value, sizeof(value));
        if (!hit) break;
        at = hit + step;
    }
    return out;
}

static const char *bt_str_join(BtList *parts, const char *sep) {
    if (!parts || parts->len == 0) return "";
    if (!sep) sep = "";
    size_t total = 1;
    for (int64_t i = 0; i < parts->len; i++) {
        const char **p = (const char **)bt_list_get(parts, i, bt_line);
        total += strlen(*p ? *p : "");
    }
    total += strlen(sep) * (size_t)(parts->len - 1);
    char *out = (char *)malloc(total);
    if (!out) bt_panic("out of memory", bt_line);
    out[0] = '\0';
    for (int64_t i = 0; i < parts->len; i++) {
        const char **p = (const char **)bt_list_get(parts, i, bt_line);
        if (i) strcat(out, sep);
        strcat(out, *p ? *p : "");
    }
    return out;
}

/* -- files ------------------------------------------------------------ */

typedef struct BtFile { FILE *fp; } BtFile;
typedef struct { BtFile *f0; bool f1; } bt_fopen_result;
typedef struct { const char *f0; bool f1; } bt_readfile_result;
typedef struct { const char *f0; bool f1; } bt_file_line_result;
typedef struct { BtList *f0; bool f1; } bt_str_list_result;

static bt_fopen_result bt_fopen(const char *path, const char *mode) {
    bt_fopen_result r = {NULL, false};
    FILE *fp = fopen(path, mode);
    if (!fp) return r;
    BtFile *f = (BtFile *)malloc(sizeof(BtFile));
    if (!f) { fclose(fp); bt_panic("out of memory", bt_line); }
    f->fp = fp;
    r.f0 = f;
    r.f1 = true;
    return r;
}

static void bt_file_check(BtFile *f, int64_t line) {
    if (!f || !f->fp) bt_panic("file is closed", line);
}

static bool bt_file_write(BtFile *f, const char *s, int64_t line) {
    bt_file_check(f, line);
    if (!s) s = "";
    return fwrite(s, 1, strlen(s), f->fp) == strlen(s);
}

static bt_file_line_result bt_file_line(BtFile *f, int64_t line) {
    bt_file_line_result r = {"", false};
    bt_file_check(f, line);
    char *buf = NULL;
    size_t cap = 0;
    ssize_t n = getline(&buf, &cap, f->fp);
    if (n < 0) { free(buf); return r; }
    while (n > 0 && (buf[n - 1] == '\n' || buf[n - 1] == '\r')) buf[--n] = '\0';
    r.f0 = buf;
    r.f1 = true;
    return r;
}

static const char *bt_file_read(BtFile *f, int64_t n, int64_t line) {
    bt_file_check(f, line);
    if (n < 0) n = 0;
    char *buf = (char *)malloc((size_t)n + 1);
    if (!buf) bt_panic("out of memory", bt_line);
    size_t got = fread(buf, 1, (size_t)n, f->fp);
    buf[got] = '\0';
    return buf;
}

static void bt_file_close(BtFile *f, int64_t line) {
    bt_file_check(f, line);
    fclose(f->fp);
    f->fp = NULL;
}

static bool bt_file_seek(BtFile *f, int64_t pos, int64_t line) {
    bt_file_check(f, line);
    if (pos < 0) return false;
    return fseek(f->fp, (long)pos, SEEK_SET) == 0;
}

static int64_t bt_file_tell(BtFile *f, int64_t line) {
    bt_file_check(f, line);
    long pos = ftell(f->fp);
    return pos < 0 ? -1 : (int64_t)pos;
}

static bt_readfile_result bt_readfile(const char *path) {
    bt_readfile_result r = {"", false};
    FILE *fp = fopen(path, "rb");
    if (!fp) return r;
    if (fseek(fp, 0, SEEK_END) != 0) { fclose(fp); return r; }
    long n = ftell(fp);
    if (n < 0) { fclose(fp); return r; }
    rewind(fp);
    char *buf = (char *)malloc((size_t)n + 1);
    if (!buf) { fclose(fp); bt_panic("out of memory", bt_line); }
    size_t got = fread(buf, 1, (size_t)n, fp);
    buf[got] = '\0';
    fclose(fp);
    r.f0 = buf;
    r.f1 = true;
    return r;
}

static bool bt_writefile(const char *path, const char *text) {
    FILE *fp = fopen(path, "wb");
    if (!fp) return false;
    if (!text) text = "";
    size_t n = strlen(text);
    bool ok = fwrite(text, 1, n, fp) == n;
    fclose(fp);
    return ok;
}

static char bt_fs_error[512] = "";

static bool bt_fs_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static bool bt_fs_mkdir(const char *path) {
    if (mkdir(path, 0777) == 0) { bt_fs_error[0] = '\0'; return true; }
    snprintf(bt_fs_error, sizeof(bt_fs_error), "%s: %s", path, strerror(errno));
    return false;
}

static bool bt_fs_remove(const char *path) {
    if (remove(path) == 0) { bt_fs_error[0] = '\0'; return true; }
    snprintf(bt_fs_error, sizeof(bt_fs_error), "%s: %s", path, strerror(errno));
    return false;
}

static const char *bt_fs_err(void) {
    return bt_fs_error;
}

static bt_str_list_result bt_fs_list(const char *path) {
    bt_str_list_result r = {NULL, false};
    DIR *d = opendir(path);
    if (!d) {
        snprintf(bt_fs_error, sizeof(bt_fs_error), "%s: %s", path, strerror(errno));
        return r;
    }
    BtList *l = bt_list_new(sizeof(const char *), 8);
    struct dirent *entry;
    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        const char *name = bt_str_dup(entry->d_name);
        l = bt_list_push(l, &name, sizeof(const char *));
    }
    closedir(d);
    bt_fs_error[0] = '\0';
    r.f0 = l;
    r.f1 = true;
    return r;
}

/* -- rand and time ---------------------------------------------------- */

static int64_t bt_rand_int(int64_t lo, int64_t hi) {
    if (hi < lo) { int64_t t = lo; lo = hi; hi = t; }
    uint64_t span = (uint64_t)(hi - lo) + 1;
    return lo + (int64_t)((uint64_t)rand() % span);
}

static double bt_rand_float(void) {
    return (double)rand() / (double)RAND_MAX;
}

static void bt_rand_seed(int64_t seed) {
    srand((unsigned int)seed);
}

static int64_t bt_ms(clockid_t clock) {
    struct timespec ts;
    clock_gettime(clock, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

static int64_t bt_time_now(void) { return bt_ms(CLOCK_REALTIME); }

static int64_t bt_time_tick(void) {
    static int64_t start = -1;
    if (start < 0) start = bt_ms(CLOCK_MONOTONIC);
    return bt_ms(CLOCK_MONOTONIC) - start;
}

/* -- tasks ------------------------------------------------------------ */

typedef struct BtTask { int64_t result; bool done; } BtTask;

static BtTask *bt_task_new(int64_t result) {
    BtTask *t = (BtTask *)malloc(sizeof(BtTask));
    if (!t) bt_panic("out of memory", bt_line);
    t->result = result;
    t->done = true;
    return t;
}

static void bt_task_wait(int64_t ms) {
    if (ms <= 0) return;
    struct timespec ts;
    ts.tv_sec = (time_t)(ms / 1000);
    ts.tv_nsec = (long)((ms % 1000) * 1000000);
    nanosleep(&ts, NULL);
}

static int64_t bt_task_join(BtTask *t) {
    return t ? t->result : 0;
}

static void bt_task_stop(BtTask *t) {
    (void)t;
}

/* -- memory ----------------------------------------------------------- */

static void *bt_alloc(int64_t count, size_t elem, int64_t line) {
    if (count < 0) bt_panic("negative allocation count", line);
    void *p = calloc((size_t)count ? (size_t)count : 1, elem);
    if (!p) bt_panic("out of memory", line);
    return p;
}

static char *bt_cstr(const char *s) {
    return (char *)(s ? s : "");
}
"""


def prelude():
    return PRELUDE
